INSERT INTO PnS.Schema_MRDFRequest (Id, FieldName, Type, StartPosition, Length, IsActive, Description, Comments, SampleValue, DataType, DataFormatTemplate, DefaultValue) VALUES (10, 'JobId', 'ASCII_Alpha', 8, 10, 1, 'The va lue in this field mus t ma tch the ba rcoded Job Id tha t is printe d on the input documents , so tha t there  is no doubt tha t the phys ica l ma te ria l loa ded for the job should be run us ing the Input file tha t wa s opened. It is highly recomme nded tha t this va lue is unique for a give n ma iling cycle .', 'Unique number generated from our sIde.   Should it be unique per day or it shuold be always unique for lifetime?', '', 'int', '{0:d<len>}', NULL)
INSERT INTO PnS.Schema_MRDFRequest (Id, FieldName, Type, StartPosition, Length, IsActive, Description, Comments, SampleValue, DataType, DataFormatTemplate, DefaultValue) VALUES (15, 'PieceId', 'ASCII_Number', 18, 4, 1, 'The va lue in this field mus t ma tch the ba rcoded Piece Id tha t is printed on the input docume nts . It is the link be twe en the scan code and the ma ilpiece record within the Input file tha t conta ins the as s e mbly  ins tructions for tha t ma ilpiece. This va lue mus t be unique for ea ch ma ilpiece, and mus t incre ment by 1 for ea ch record within the file.', 'Mailpiece means one loan PDF.', '', 'int', '{0:d<len>}', NULL)
INSERT INTO PnS.Schema_MRDFRequest (Id, FieldName, Type, StartPosition, Length, IsActive, Description, Comments, SampleValue, DataType, DataFormatTemplate, DefaultValue) VALUES (20, 'TotalSheets', 'ASCII_Alpha', 22, 3, 1, 'This field Identifies the tota l numbe r of phys ica l she ets of pa per tha t should be fe d from the input fe ede r for the ma ilpiece. If you ha ve multiple input fe eders , you will nee d a Tota l Sheets field for ea ch input fe eder. There are two of the s e fields availa ble to a ccommoda te as ma ny as two input fee ders on the ins e rter (e .g., a RAT1 with ea s t and north feeder inputs ).', 'Number of physical papers in that loan required to print pages.', '', 'int', '{0:d<len>}', NULL)
INSERT INTO PnS.Schema_MRDFRequest (Id, FieldName, Type, StartPosition, Length, IsActive, Description, Comments, SampleValue, DataType, DataFormatTemplate, DefaultValue) VALUES (25, 'InputWeight', 'ASCII_Alpha', 25, 5, 1, 'This field mus t conta in a va lue. Eithe r enter 0.000 (when all input document pa ge s weigh the sa me), or enter the finis hed a ccumula te d we ight of the input documents  (when diffe rent weighte d pa per is us ed within the input feede r).This field mus t be a decima l number with one digit to the left of the de cima l point, and three digits to the right (e.g., 1.020). IMPORTANT NOTE: Whe n diffe rent weighted input documents  are not us ed, the a mount of pos ta ge a pplied is ba s ed on the weight tha t tha t is s pecifie d in the input fe ede r setup s creen. Ea ch time a pa ge is fed, the we ight for an indivIdua l she et is added to the tota l. If there is a va lue grea ter tha n zero in this field, it too will be a dde d to the tota l weight, and there fore the mete r will add pos ta ge ba s e d on a we ight tha t is he a vie r tha n the ma ilpie ce a ctua lly is . IMPORTANT NOTE: Whe n diffe rent weighted input documents  are us ed, enter the tota l weight for the input pa ge s in this field, and specify 0.000 for the weight within the input fee der setup scree n so tha t a dditiona l we ight is not added to the tota l accumula ted weight.', 'For us always 0.000', '0', 'varchar(255)', '{0,-<len>}', '0')
INSERT INTO PnS.Schema_MRDFRequest (Id, FieldName, Type, StartPosition, Length, IsActive, Description, Comments, SampleValue, DataType, DataFormatTemplate, DefaultValue) VALUES (30, 'Feeder3_Sel', 'ASCII_Alpha', 30, 1, 1, 'This field specifies whether an ins ert fee der should feed an ins ert or not feed an ins ert. Possible va lue s for this fie ld are: 0 = Don’t fe ed, 1 = Feed.', '', '0', 'varchar(255)', '{0,-<len>}', '0')
